+      return ((VcsFileRevision)object).getRevisionNumber().asString();
+    }
+  };
+
+  public static final DualViewColumnInfo DATE = new VcsColumnInfo("Date") {
+    protected Comparable getDataOf(Object object) {
+      Date date = ((VcsFileRevision)object).getRevisionDate();
+      if (date == null) return "";
+      return DATE_FORMAT.format(date);
+    }
+
+    public int compare(Object o1, Object o2) {
+      return ((VcsFileRevision)o1).getRevisionDate()
+        .compareTo(((VcsFileRevision)o2).getRevisionDate());
+    }
+  };
+
+  public static final DualViewColumnInfo AUTHOR = new VcsColumnInfo("Author") {
+    protected Comparable getDataOf(Object object) {
+      return ((VcsFileRevision)object).getAuthor();
+    }
+  };
+
+  public static final DualViewColumnInfo MESSAGE = new VcsColumnInfo(COMMIT_MESSAGE_TITLE) {
+    protected Comparable getDataOf(Object object) {
+      String commitMessage = ((VcsFileRevision)object).getCommitMessage();
+      try {
+        List<byte[]> lines = new LineReader().readLines(new ByteArrayInputStream(commitMessage.getBytes()));
+        if (!lines.isEmpty()) {
+          int lastIndex = lines.size() - 1;
+          if (lines.get(lastIndex).length == 0) lines.remove(lastIndex);
+        }
+        if (lines.isEmpty()) return "";
